import React, { useState } from 'react';
import axios from 'axios';

function BookingForm({ slot, onBooked }) {
  if (!slot) {
    return <p>Loading slot details...</p>;
  }

  const [vehicleNumber, setVehicleNumber] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [error, setError] = useState('');
  const [estimatedCost, setEstimatedCost] = useState(0);

  const calculateCost = (start, end) => {
    const startDate = new Date(start);
    const endDate = new Date(end);
    const duration = (endDate - startDate) / (1000 * 60 * 60); // in hours
    return Math.max(0, duration * slot.hourlyRate);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    const now = new Date();
    const selectedStart = new Date(startTime);
    const selectedEnd = new Date(endTime);

    if (selectedStart < now) {
      setError('Start time cannot be in the past');
      return;
    }

    if (selectedEnd <= selectedStart) {
      setError('End time must be after start time');
      return;
    }

    const cost = calculateCost(startTime, endTime);
    setEstimatedCost(cost);

    try {
      const response = await axios.post('http://localhost:8080/api/bookings', {
        slotId: slot.id,
        vehicleNumber,
        startTime,
        endTime,
        estimatedCost: cost,
      });

      onBooked(response.data);
    } catch (err) {
      setError('Booking failed. Please try again.');
    }
  };

  return (
    <div>
      <h2>Book Slot {slot?.slotNumber}</h2>

      <form onSubmit={handleSubmit}>
        <div>
          <label>Vehicle Number:</label>
          <input
            type="text"
            value={vehicleNumber}
            onChange={(e) => setVehicleNumber(e.target.value)}
            required
          />
        </div>

        <div>
          <label>Start Time:</label>
          <input
            type="datetime-local"
            value={startTime}
            onChange={(e) => {
              setStartTime(e.target.value);
              setEstimatedCost(calculateCost(e.target.value, endTime));
            }}
            required
          />
        </div>

        <div>
          <label>End Time:</label>
          <input
            type="datetime-local"
            value={endTime}
            onChange={(e) => {
              setEndTime(e.target.value);
              setEstimatedCost(calculateCost(startTime, e.target.value));
            }}
            required
          />
        </div>

        {estimatedCost > 0 && (
          <div>
            <strong>Estimated Cost:</strong> ${estimatedCost.toFixed(2)}
          </div>
        )}

        {error && <p style={{ color: 'red' }}>{error}</p>}

        <button type="submit">Book</button>
      </form>
    </div>
  );
}

export default BookingForm;
